package com.inridemart.order;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
@RestController @RequestMapping("/api/v1/orders") public class OrderController { final OrderService service; OrderController(OrderService s){service=s;} @PostMapping public ResponseEntity<Response> create(Authentication a,@RequestHeader("Idempotency-Key") @NotBlank String key,@Valid @RequestBody Request r){return ResponseEntity.status(HttpStatus.CREATED).body(Response.of(service.create((UUID)a.getPrincipal(),key,r.items().stream().map(i->new OrderService.Line(i.productId(),i.quantity())).toList())));} @GetMapping public List<Response> mine(Authentication a){return service.mine((UUID)a.getPrincipal()).stream().map(Response::of).toList();} @GetMapping("/{id}") public Response one(Authentication a,@PathVariable("id")UUID id){return Response.of(service.mine((UUID)a.getPrincipal(),id));} @GetMapping("/{id}/tracking") public Tracking tracking(Authentication a,@PathVariable("id") UUID id){return Tracking.of(service.mine((UUID)a.getPrincipal(),id));} @PostMapping("/{id}/payment") public Response paid(Authentication a,@PathVariable("id") UUID id){return Response.of(service.updateStatus((UUID)a.getPrincipal(),id,OrderStatus.CONFIRMED));} @PatchMapping("/{id}/tracking") public Response updateTracking(Authentication a,@PathVariable("id") UUID id,@Valid @RequestBody TrackingUpdate update){return Response.of(service.updateStatus((UUID)a.getPrincipal(),id,update.status()));} record Request(@NotEmpty List<Item> items){} record Item(@NotNull UUID productId,@Min(1) int quantity){} record TrackingUpdate(@NotNull OrderStatus status){} record Tracking(UUID orderId,OrderStatus status){static Tracking of(Order o){return new Tracking(o.id(),o.status());}} record Response(UUID id,OrderStatus status,List<Line> items,BigDecimal totalAmount,String currency,Instant createdAt){static Response of(Order o){return new Response(o.id(),o.status(),o.items().stream().map(i->new Line(i.productId(),i.productName(),i.quantity(),i.unitPrice())).toList(),o.totalAmount(),o.currency(),o.createdAt());}} record Line(UUID productId,String productName,int quantity,BigDecimal unitPrice){} }
